#include "CUDACore/cudastdAlgorithm.h"
#include <algorithm>
#include <iostream>
#include <iterator>
#include <vector>


// The following comment is generated by an LLM. 
/**
 * Tests binary find functionality with duplicate values in a sorted vector.
  * Finds the first occurrence of a specified value within a sorted range.
 * @param first beginning of the sorted range
 * @param last end of the sorted range
 * @param val value to be searched
 * @return iterator pointing to the first occurrence of val
  * Finds the last occurrence of a specified value within a sorted range.
 * @param first beginning of the sorted range
 * @param last end of the sorted range
 * @param val value to be searched
 * @return iterator pointing to the position after the last occurrence of val
  * Performs a classic binary search on a sorted range to find an element.
 * @param first beginning of the sorted range
 * @param last end of the sorted range
 * @param val value to be searched
 * @return iterator pointing to val if found, otherwise end of range
 */void testBinaryFind() {
  std::vector<int> data = {1, 1, 2, 3, 3, 3, 3, 4, 4, 4, 5, 5, 6};

  auto lower = hip_std::lower_bound(data.begin(), data.end(), 4);
  auto upper = hip_std::upper_bound(data.begin(), data.end(), 4);

  std::copy(lower, upper, std::ostream_iterator<int>(std::cout, " "));

  std::cout << '\n';

  // classic binary search, returning a value only if it is present

  data = {1, 2, 4, 6, 9, 10};

  auto test = [&](auto v) {
    auto it = hip_std::binary_find(data.cbegin(), data.cend(), v);

    if (it != data.cend())
      std::cout << *it << " found at index " << std::distance(data.cbegin(), it) << std::endl;
    else
      std::cout << v << " non found" << std::endl;
  };

  test(4);
  test(5);
}

int main() { testBinaryFind(); }
